describe('Image Paste from Clipboard Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="upload-area"]').should('be.visible');
  });

  it('should successfully paste an image from clipboard into upload area', () => {
    const fileName = 'test-image.png';
    const fileType = 'image/png';

    cy.fixture('images/sample.png', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent, fileType))
      .then(blob => {
        const dataTransfer = new DataTransfer();
        const file = new File([blob], fileName, { type: fileType });
        dataTransfer.items.add(file);

        cy.get('[data-testid="upload-area"]')
          .trigger('paste', { clipboardData: dataTransfer });
      });

    cy.get('[data-testid="upload-preview"]').should('be.visible');
    cy.get('[data-testid="file-name"]').should('contain', fileName);
    cy.get('[data-testid="upload-status"]').should('contain', 'Success');
  });

  it('should handle paste of non-image file gracefully', () => {
    const fileName = 'document.txt';
    const fileType = 'text/plain';

    cy.fixture('files/sample.txt', 'utf8')
      .then(fileContent => Cypress.Blob.stringToBlob(fileContent, fileType))
      .then(blob => {
        const dataTransfer = new DataTransfer();
        const file = new File([blob], fileName, { type: fileType });
        dataTransfer.items.add(file);

        cy.get('[data-testid="upload-area"]')
          .trigger('paste', { clipboardData: dataTransfer });
      });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please upload an image file');
    cy.get('[data-testid="upload-preview"]').should('not.exist');
  });

  it('should handle empty clipboard paste', () => {
    const dataTransfer = new DataTransfer();

    cy.get('[data-testid="upload-area"]')
      .trigger('paste', { clipboardData: dataTransfer });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No file found in clipboard');
  });

  it('should display image preview after successful paste', () => {
    const fileName = 'preview-test.png';
    const fileType = 'image/png';

    cy.fixture('images/sample.png', 'binary')
      .then(fileContent => Cypress.Blob.binaryStringToBlob(fileContent, fileType))
      .then(blob => {
        const dataTransfer = new DataTransfer();
        const file = new File([blob], fileName, { type: fileType });
        dataTransfer.items.add(file);

        cy.get('[data-testid="upload-area"]')
          .trigger('paste', { clipboardData: dataTransfer });
      });

    cy.get('[data-testid="upload-preview"] img').should('be.visible');
    cy.get('[data-testid="upload-preview"] img').should('have.attr', 'src');
    cy.get('[data-testid="file-size"]').should('not.be.empty');
  });
});
